alter table private.player_sect_states add column if not exists sect_name text not null default '',add column if not exists sect_star integer not null default 0 check(sect_star between 0 and 9),add column if not exists sect_faction text not null default '' check(sect_faction in('','正','邪')),add column if not exists membership_imported boolean not null default false,add column if not exists last_left_at timestamptz;
create or replace function private.sect_catalog() returns table(name text,star integer,faction text,invitation_index integer) language sql immutable set search_path='' as $$values
('青竹門',1,'正',1),('清溪派',1,'正',2),('松風堂',1,'正',3),('白石觀',1,'正',4),('黑風寨',1,'邪',5),('赤蛇幫',1,'邪',6),('斷刃堂',1,'邪',7),
