('青鸞劍宗',3,'正',17),('百草仙門',3,'正',18),('紫陽宮',3,'正',19),('天河書院',3,'正',20),('鎮岳宗',3,'正',21),('九煞宗',3,'邪',22),('玄屍門',3,'邪',23),('萬毒谷',3,'邪',24),('奪魄宮',3,'邪',25),('赤煉魔宗',3,'邪',26),
('太虛劍派',4,'正',27),('五雷天宗',4,'正',28),('蓬萊仙宮',4,'正',29),('星辰道門',4,'正',30),('乾元宗',4,'正',31),('黃泉殿',4,'邪',32),('萬妖天府',4,'邪',33),('焚心魔教',4,'邪',34),
('神霄天宮',5,'正',35),('滄海龍門',5,'正',36),('玄天劍庭',5,'正',37),('終南紫府',5,'正',38),('冥獄魔都',5,'邪',39),('合歡天宗',5,'邪',40),('幽冥血海',5,'邪',41),
('萬壽仙山',6,'正',42),('梵天聖宗',6,'正',43),('六道玄宮',6,'正',44),('歸墟仙門',6,'正',45),('太古魔殿',6,'邪',46),('吞天妖庭',6,'邪',47),('絕情天宮',6,'邪',48),
('無上劍閣',7,'正',49),('蒼穹道統',7,'正',50),('玉虛仙府',7,'正',51),('昆吾魔山',7,'邪',52),('十方邪樓',7,'邪',53),('彼岸花宮',7,'邪',54),
('昊天聖宮',8,'正',55),('須彌神山',8,'正',56),('太初龍院',8,'正',57),('玄陰帝谷',8,'邪',58),('葬月魔宗',8,'邪',59),('燭龍神庭',8,'邪',60),
('太上白玉京',9,'正',61),('諸天星羅神宗',9,'正',62),('九霄凌天仙宮',9,'正',63),('永劫輪迴殿',9,'邪',64),('無極天魔聖宗',9,'邪',65),('太古神夢天宮',9,'邪',66)$$;
create or replace function private.sect_snapshot(s private.player_sect_states) returns jsonb language sql stable set search_path='' as $$select jsonb_build_object('revision',s.revision,'sectName',s.sect_name,'sectStar',s.sect_star,'sectFaction',s.sect_faction,'sectRank',s.sect_rank,'actingLeader',s.acting_leader,'lastSalaryDay',s.last_salary_day,'lastPracticeDay',s.last_practice_day,'practiceUntil',s.practice_until)$$;

create or replace function public.player_sect_membership_bootstrap(p_channel text,p_sect_name text,p_sect_star integer,p_sect_faction text) returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());s private.player_sect_states;c record;begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test') then raise exception '版本不正確';end if;insert into private.player_sect_states(user_id,channel) values(uid,p_channel) on conflict do nothing;select * into s from private.player_sect_states where user_id=uid and channel=p_channel for update;if not s.membership_imported then if coalesce(p_sect_name,'')<>'' then select * into c from private.sect_catalog() where name=p_sect_name;if c.name is null or c.star<>p_sect_star or c.faction<>p_sect_faction then raise exception '門派資料不正確';end if;update private.player_sect_states set sect_name=c.name,sect_star=c.star,sect_faction=c.faction,membership_imported=true,revision=revision+1,updated_at=now() where user_id=uid and channel=p_channel returning * into s;else update private.player_sect_states set membership_imported=true where user_id=uid and channel=p_channel returning * into s;end if;end if;return private.sect_progress_snapshot(s);end $$;

create or replace function public.player_sect_membership(p_channel text,p_action text,p_sect_name text default null,p_invitation_key text default null,p_request_id uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());s private.player_sect_states;p private.player_progression_states;c record;b private.player_mail_item_balances;max_star integer;begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test') or p_action not in('join','leave') or p_request_id is null then raise exception '門派請求不正確';end if;if exists(select 1 from private.player_state_events where user_id=uid and channel=p_channel and request_id=p_request_id) then raise exception '重複的門派請求';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-sect-membership-'||p_channel));select * into s from private.player_sect_states where user_id=uid and channel=p_channel for update;select * into p from private.player_progression_states where user_id=uid and channel=p_channel;if s.user_id is null or p.user_id is null then raise exception '伺服器角色狀態尚未建立';end if;if p_action='leave' then if s.sect_name='' then raise exception '目前無門無派';end if;update private.player_sect_states set sect_name='',sect_star=0,sect_faction='',sect_rank=0,acting_leader=false,task_id='',last_left_at=now(),revision=revision+1,updated_at=now() where user_id=uid and channel=p_channel returning * into s;else if s.sect_name<>'' then raise exception '已有門派';end if;select * into c from private.sect_catalog() where name=p_sect_name;if c.name is null then raise exception '找不到此門派';end if;max_star:=least(9,greatest(p.spirit_level/10+1,p.sword_level/10+1,p.body_level/4+1));if c.star>max_star then raise exception '目前境界不足';end if;if p_invitation_key is null then if s.last_left_at is not null and s.last_left_at>now()-interval '45 minutes' then raise exception '門派尋訪尚在冷卻';end if;else if p_invitation_key<>'sectInvitationCount'||c.invitation_index then raise exception '門派信物不符';end if;select * into b from private.player_mail_item_balances where user_id=uid and channel=p_channel and item_key=p_invitation_key for update;if b.user_id is null or b.amount<1 then raise exception '伺服器門派信物不足';end if;update private.player_mail_item_balances set amount=amount-1,updated_at=now() where user_id=uid and channel=p_channel and item_key=p_invitation_key returning * into b;end if;update private.player_sect_states set sect_name=c.name,sect_star=c.star,sect_faction=c.faction,sect_rank=0,acting_leader=false,sect_merit=0,sect_contribution=0,task_id='',revision=revision+1,updated_at=now() where user_id=uid and channel=p_channel returning * into s;end if;insert into private.player_state_events(user_id,channel,revision,event_type,request_id,payload) values(uid,p_channel,s.revision,'sect_'||p_action,p_request_id,jsonb_build_object('sect',s.sect_name));return jsonb_build_object('sect',private.sect_progress_snapshot(s),'itemBalances',case when b.user_id is null then '{}'::jsonb else jsonb_build_object(b.item_key,b.amount) end);end $$;

revoke all on function private.sect_catalog() from public,anon,authenticated;
revoke execute on function public.player_sect_membership_bootstrap(text,text,integer,text),public.player_sect_membership(text,text,text,text,uuid) from public,anon;
grant execute on function public.player_sect_membership_bootstrap(text,text,integer,text),public.player_sect_membership(text,text,text,text,uuid) to authenticated;
